import json
import re
from html.parser import HTMLParser

class TableParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.rows = []
        self.current_row = []

    def handle_starttag(self, tag, attrs):
        if tag == 'td' or tag == 'th':
            self.current_data = ''

    def handle_endtag(self, tag):
        if tag == 'td' or tag == 'th':
            if self.current_data.strip():
                self.current_row.append(self.current_data.strip())
        if tag == 'tr':
            if self.current_row:
                self.rows.append(self.current_row)
            self.current_row = []

    def handle_data(self, data):
        self.current_data += data

for year in ['2010', '2011', '2012', '2013']:
    data = json.load(open(f'/app/resources/treasury_bulletin_{year}_09.json'))
    elements = data['document']['elements']

    # Find the IFS-1 table
    for el in elements:
        content = el.get('content', '')
        if '<table><tr><th>End of calendar year or month</th>' in content:
            parser = TableParser()
            parser.feed(content)

            # Find July row
            for row in parser.rows:
                if len(row) >= 6 and 'July' in row[0]:
                    print(f'{year} July:', row)
            break
"
